==== 808efb32
808efb32 Explicitly check for bps == 0 when applying replaygain
 src/flac/decode.c | 7 +++++++
 1 file changed, 7 insertions(+)
commit 808efb328717af811d24a8d59fdcc73f5f328b01
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Fri May 19 08:12:55 2023 +0200

    Explicitly check for bps == 0 when applying replaygain

    During application of replaygain, bps is checked to be > 0. This
    should never happen in a valid file. This check is specific for
    replaygain application instead of more generic (at streaminfo)
    because we still want to be able to recover files in which
    streaminfo is invalid or missing.

diff --git a/src/flac/decode.c b/src/flac/decode.c
index d874b4b8..bb39fcd2 100644
--- a/src/flac/decode.c
+++ b/src/flac/decode.c
@@ -1543,6 +1543,13 @@ void metadata_callback(const FLAC__StreamDecoder *decoder, const FLAC__StreamMet
                                        return;
                                }
                        }
+                       else if(decoder_session->bps == 0) {
+                               flac__utils_printf(stderr, 1, "%s: WARNING: can't apply ReplayGain, bit-per-sample value is invalid\n", decoder_session->inbasefilename);
+                               if(decoder_session->treat_warnings_as_errors) {
+                                       decoder_session->abort_flag = true;
+                                       return;
+                               }
+                       }
                        else {
                                const char *ls[] = { "no", "peak", "hard" };
                                const char *ns[] = { "no", "low", "medium", "high" };
==== defad5b5
defad5b5 Turn replaygain application off when impossible
 src/flac/decode.c | 1 +
 1 file changed, 1 insertion(+)
commit defad5b5442550a9bd678076fe7ad125edb9f087
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Tue Jul 23 08:24:20 2024 +0200

    Turn replaygain application off when impossible

    Addition to commit 808efb3. That commit threw a warning, but did
    not actually turn off replaygain application.

    Credit: Oss-Fuzz
    Issue: https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=70482

diff --git a/src/flac/decode.c b/src/flac/decode.c
index 6a89b144..099348b6 100644
--- a/src/flac/decode.c
+++ b/src/flac/decode.c
@@ -1590,6 +1590,7 @@ void metadata_callback(const FLAC__StreamDecoder *decoder, const FLAC__StreamMet
                                        decoder_session->abort_flag = true;
                                        return;
                                }
+                               decoder_session->replaygain.apply = false;
                        }
                        else {
                                const char *ls[] = { "no", "peak", "hard" };
==== 215d1aa6
215d1aa6 Do not try to apply replaygain when bps < 4 or bps > 24
 src/flac/decode.c | 8 ++++++++
 1 file changed, 8 insertions(+)
commit 215d1aa633b218ae16bfc1b09aed6f3f7a22d19e
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Tue Jul 23 08:29:08 2024 +0200

    Do not try to apply replaygain when bps < 4 or bps > 24

diff --git a/src/flac/decode.c b/src/flac/decode.c
index 099348b6..8e73a933 100644
--- a/src/flac/decode.c
+++ b/src/flac/decode.c
@@ -1592,6 +1592,14 @@ void metadata_callback(const FLAC__StreamDecoder *decoder, const FLAC__StreamMet
                                }
                                decoder_session->replaygain.apply = false;
                        }
+                       else if(decoder_session->bps < 4 || decoder_session->bps > 24) {
+                               flac__utils_printf(stderr, 1, "%s: WARNING: can't apply ReplayGain, bit-per-sample value must be between 4 and 24\n", decoder_session->inbasefilename);
+                               if(decoder_session->treat_warnings_as_errors) {
+                                       decoder_session->abort_flag = true;
+                                       return;
+                               }
+                               decoder_session->replaygain.apply = false;
+                       }
                        else {
                                const char *ls[] = { "no", "peak", "hard" };
                                const char *ns[] = { "no", "low", "medium", "high" };
==== e50c876a
e50c876a Do not try to apply replaygain when bps changes
 src/flac/decode.c | 4 ++++
 1 file changed, 4 insertions(+)
commit e50c876a1c0348c23f26b2ee348a2dee40c9d23b
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Thu Jul 25 12:49:00 2024 +0200

    Do not try to apply replaygain when bps changes

    Credit: Oss-Fuzz
    Issue: N/A

diff --git a/src/flac/decode.c b/src/flac/decode.c
index 8e73a933..4d7eb310 100644
--- a/src/flac/decode.c
+++ b/src/flac/decode.c
@@ -1154,6 +1154,10 @@ FLAC__StreamDecoderWriteStatus write_callback(const FLAC__StreamDecoder *decoder
                                flac__utils_printf(stderr, 1, "%s: ERROR, bits-per-sample is %u in this frame but %u in previous frames\n", decoder_session->inbasefilename, bps, decoder_session->bps);
                        if(!decoder_session->continue_through_decode_errors)
                                return FLAC__STREAM_DECODER_WRITE_STATUS_ABORT;
+                       else if(decoder_session->replaygain.apply) {
+                               flac__utils_printf(stderr, 1, "%s: ERROR, cannot decode through previous error with replaygain application turned on\n", decoder_session->inbasefilename, bps, decoder_session->bps);
+                               return FLAC__STREAM_DECODER_WRITE_STATUS_ABORT;
+                       }
                }
        }
        else {
